<script>
  export let icon = "";
  export let size = "20px";

  let urls = {
    restart: "icons/restart.png",
    driving: "icons/driving.png",
    navigation: "icons/navigation.png",
    keyboard: "icons/keyboard.png",
    swap: "icons/swap.png",
  };

  let alts = {
    restart: "Restart Game",
    driving: "Driver",
    navigation: "Navigator",
    keyboard: "Keyboard",
    swap: "Swap roles",
  };
</script>

<img
  style="--size: {size}"
  src={urls[icon]}
  alt={alts[icon]}
  title={alts[icon]}
/>

<style>
  img {
    height: var(--size);
    width: var(--size);
    /* the icons are black line art on white; invert them and let the dark
       page show through the (now black) background */
    filter: invert(0.85);
    mix-blend-mode: lighten;
  }
</style>
